Clase PilaUno
    Privado Definir valor Como Entero;

    Metodo Constructor()
        Este.valor <- 0;
    FinMetodo

    Publico Metodo Apilar(unValor Como Entero)
        Este.valor <- unValor;
    FinMetodo

    Publico Metodo Desapilar() Como Entero
        Retornar Este.valor;
    FinMetodo
FinClase

Proceso EjecutarPila
    Definir n Como Entero;
    Definir pila Como PilaUno;
    Leer n;
    pila <- Nuevo PilaUno();
    pila.Apilar(n);
    Escribir pila.Desapilar();
FinProceso
